G=load(); D=G['Demo pair 1 input']; O=G['Demo pair 1 output']; T=G['Test input']

def components(g,bg):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; comps=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]!=bg and not seen[r][c]:
                q=deque([(r,c)]); seen[r][c]=True; cl=[]
                while q:
                    y,x=q.popleft(); cl.append((y,x,g[y][x]))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        yy,xx=y+dy,x+dx
                        if 0<=yy<H and 0<=xx<W and g[yy][xx]!=bg and not seen[yy][xx]:
                            seen[yy][xx]=True; q.append((yy,xx))
                comps.append(cl)
    return comps

def f(g):
    bg=g[0][0]; comps=components(g,bg)
    comps.sort(key=len, reverse=True)
    pat=comps[0]; marks=comps[1:]
    rs=[p[0] for p in pat]; cs=[p[1] for p in pat]
    r0,c0=min(rs),min(cs); h=max(rs)-r0+1; w=max(cs)-c0+1
    patgrid=[[g[r0+i][c0+j] for j in range(w)] for i in range(h)]
    cr,cc=(h-1)//2,(w-1)//2
    out=[row[:] for row in g]
    for comp in marks:
        mr,mc,_=comp[0]
        tr,tc=mr-cr,mc-cc
        for i in range(h):
            for j in range(w):
                rr,ccc=tr+i,tc+j
                if 0<=rr<len(g) and 0<=ccc<len(g[0]):
                    out[rr][ccc]=patgrid[i][j]
    return out

